import{_ as t,o as e,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"nanoMuse 品牌","description":"","frontmatter":{},"headers":[],"relativePath":"zh/brand.md","filePath":"zh/brand.md"}'),r={name:"zh/brand.md"};function c(n,d,i,s,l,h){return e(),o("div",null,[...d[0]||(d[0]=[a('<h1 id="nanomuse-品牌" tabindex="-1">nanoMuse 品牌 <a class="header-anchor" href="#nanomuse-品牌" aria-label="Permalink to &quot;nanoMuse 品牌&quot;">​</a></h1><p>2026-09-24 定稿。应用图标和应用内的配色体系是同一个决定：调色板由图标推导出来，这样整个应用 才会和主屏幕上的那块图标是一个样子。</p><h2 id="the-mark" tabindex="-1">标志 <a class="header-anchor" href="#the-mark" aria-label="Permalink to &quot;标志 {#the-mark}&quot;">​</a></h2><p>一笔连续的笔画，读出来是一个 <strong>N</strong>：带钩的起笔、一个圆峰、一条长斜线、一个收紧的谷、向上的收笔。 它和 Muse 的单笔标志遵循同一套视觉语法（Muse 的是三个拱的 M，我们的是一个拱的 N）——就像 OpenManus 和 Manus 押韵，却是另一个手势。标志刻意做得抽象：它先是一个手势，然后才是一个字母。</p><ul><li>源文件只有一个：<code>assets/brand/nanomuse-icon-source-1024.png</code>（最终渲染，品牌蓝底上的白色圆角方块）。 其余一切都由它派生。</li><li><code>assets/brand/nanomuse-mark.svg</code>——只有笔画本身，描成一条填充路径，viewBox <code>0 0 100 100</code>，用方块坐标，渐变填充。</li><li><code>assets/brand/nanomuse-icon.svg</code>——白色圆角方块（<code>rx=27</code>）加标志。这就是应用图标。</li><li><code>assets/brand/nanomuse-icon-on-blue.svg</code>——放在品牌蓝背景上的图标，只用于商店页面和启动页。 凡是用图标代表这个应用的地方——README、网站、社交卡片、favicon——都用素净的那块：白底、标志、 一道细边，没有背景。</li><li><code>assets/brand/nanomuse-mark-rgba-688.png</code>——带透明通道的笔画，688 px，位图兜底。</li><li><code>docs/app-icon.png</code>——带圆角渲染出来的方块（27 % 圆角半径，外侧透明，一道 <code>#D9D9DE</code> 细边， 放在白底上也保得住形状），512 px：图标在主屏幕上的样子。它是 README 的头图，也是任何把 nanoMuse 当作一个 App 展示的地方该用的那张图。</li></ul><p>图标<strong>不是</strong>吉祥物。默认的脸是随附的<strong>小龙</strong>（<code>web/public/avatars/</code>，Android 应用的 <code>avatar/</code>）； 小熊猫（<code>web/src/components/redPandaShapes.ts</code>）是用户可以挑的可选形象之一。永远不要把小熊猫 （或小龙）放到启动器图标上，也永远不要把 N 标志放进聊天里当一张脸。</p><h2 id="colour" tabindex="-1">颜色 <a class="header-anchor" href="#colour" aria-label="Permalink to &quot;颜色 {#colour}&quot;">​</a></h2><p>从图标上量出来的。</p><table tabindex="0"><thead><tr><th>令牌</th><th>值</th><th>用途</th></tr></thead><tbody><tr><td><code>brand.stroke.start</code></td><td><code>#015CFB</code></td><td>标志渐变的左端</td></tr><tr><td><code>brand.stroke.end</code></td><td><code>#0186FB</code></td><td>标志渐变的右端</td></tr><tr><td><code>brand.blue</code></td><td><code>#0078FD</code></td><td>方块背后的背景；启动页；头图背景</td></tr><tr><td><code>tile</code></td><td><code>#FFFFFF</code></td><td>图标方块</td></tr></tbody></table><h3 id="light-theme" tabindex="-1">浅色主题 <a class="header-anchor" href="#light-theme" aria-label="Permalink to &quot;浅色主题 {#light-theme}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>令牌</th><th>值</th><th>对比度</th><th>用途</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#015CFB</code></td><td>白底上 5.35</td><td>链接、主按钮（白字）、当前标签、发送按钮、状态行</td></tr><tr><td><code>primary.container</code></td><td><code>#E5F0FF</code></td><td>—</td><td>用户气泡、选中的行、标签</td></tr><tr><td><code>primary.tint</code></td><td><code>#EEF5FF</code></td><td>—</td><td>轻微高亮的表面</td></tr><tr><td><code>bg.grouped</code></td><td><code>#F2F2F7</code></td><td>—</td><td>页面背景（沿用 OpenMinis，没有改）</td></tr><tr><td><code>surface</code></td><td><code>#FFFFFF</code></td><td>—</td><td>卡片、输入框</td></tr></tbody></table><h3 id="dark-theme" tabindex="-1">深色主题 <a class="header-anchor" href="#dark-theme" aria-label="Permalink to &quot;深色主题 {#dark-theme}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>令牌</th><th>值</th><th>对比度</th><th>用途</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#58A6FF</code></td><td><code>#000</code> 上 8.3，<code>#1C1C1E</code> 上 6.7</td><td>链接、按钮（黑字）、当前标签、状态行</td></tr><tr><td><code>primary.container</code></td><td><code>#1A2B4A</code></td><td>—</td><td>用户气泡</td></tr><tr><td><code>bg</code> / <code>surface</code> / <code>surface.2</code></td><td><code>#000000</code> / <code>#1C1C1E</code> / <code>#2C2C2E</code></td><td>—</td><td>沿用 OpenMinis，没有改</td></tr></tbody></table><p>规则：强调色只有一个色相。OpenMinis 用 iOS 的蓝、橙、绿着色的代码块、思考文字和链接，一律改成 <code>primary</code> 加中性色。小熊猫身上的铁锈橙留在形象里；它不是界面颜色。</p><h2 id="android-mapping-done-in-s1" tabindex="-1">Android 映射（S1 已完成） <a class="header-anchor" href="#android-mapping-done-in-s1" aria-label="Permalink to &quot;Android 映射（S1 已完成） {#android-mapping-done-in-s1}&quot;">​</a></h2><ul><li>自适应图标：背景层 = 纯色 <code>#FFFFFF</code>；前景层 = 标志，一个 <code>VectorDrawable</code>，<code>fillColor</code> 是上面那个 两档线性渐变；单色层 = 同一条路径，平涂填充（由 Android 着色）。</li><li>图标皮肤（从 OpenMinis 保留下来的 activity 别名）：<em>自动</em> = 白色方块；<em>浅色</em> = 白色方块； <em>深色</em> = <code>#0F1B33</code> 方块加白色标志。</li><li>通知小图标：标志，平涂白色，24 dp。</li><li>永远不要发布旧的 OpenMinis 图标、名字，或者字母 n 的那些草稿。</li></ul><h2 id="don-ts" tabindex="-1">不要这样做 <a class="header-anchor" href="#don-ts" aria-label="Permalink to &quot;不要这样做 {#don-ts}&quot;">​</a></h2><ul><li>不要把标志涂成蓝色渐变、平涂白、平涂黑以外的颜色。</li><li>不要旋转、描边，也不要给笔画加阴影。</li><li>不要把标志直接放在品牌蓝上而不垫白色方块（对比度不够）。</li><li>不要把 Meta 的 Muse 标志、名字或蓝色当作素材；亲缘关系只在手势上。</li></ul>',18)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
